from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path
from typing import Literal

from claude_md.model import LoadedFile, LoadMode


@dataclass(frozen=True)
class Source:
    kind: Literal["docs", "heuristic"]
    url: str | None

    def __post_init__(self) -> None:
        if self.kind == "docs" and not self.url:
            raise ValueError("a docs source requires a url")
        if self.kind == "heuristic" and self.url is not None:
            raise ValueError("a heuristic source must not have a url")


@dataclass(frozen=True)
class Finding:
    check_id: str
    severity: Literal["issue", "warning", "suggestion"]
    path: Path | None
    line: int | None
    message: str
    fix: str
    source: Source


@dataclass(frozen=True)
class Context:
    project_dir: Path
    home_dir: Path


CheckFn = Callable[[list[LoadedFile], Context], list[Finding]]


@dataclass(frozen=True)
class CheckSpec:
    id: str
    source: Source
    weight: int
    cap: int
    fn: CheckFn


REGISTRY: dict[str, CheckSpec] = {}

_UNCHECKED_MODES = frozenset({LoadMode.EXCLUDED, LoadMode.DORMANT, LoadMode.SKIPPED})


def check(
    id: str, source: Source, weight: int, cap: int
) -> Callable[[CheckFn], CheckFn]:
    def register(fn: CheckFn) -> CheckFn:
        if id in REGISTRY:
            raise ValueError(f"duplicate check id: {id}")
        REGISTRY[id] = CheckSpec(id, source, weight, cap, fn)
        return fn

    return register


def run_checks(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    checked = [f for f in files if f.mode not in _UNCHECKED_MODES]
    results: list[Finding] = []
    for spec in REGISTRY.values():
        results.extend(spec.fn(checked, ctx))
    return results

from collections import Counter
from dataclasses import dataclass

from claude_md.findings import REGISTRY, Finding

MAX_SCORE = 100


@dataclass(frozen=True)
class Deduction:
    check_id: str
    count: int
    points: int
    capped: bool


@dataclass(frozen=True)
class Score:
    value: int
    deductions: list[Deduction]


def score(findings: list[Finding]) -> Score:
    counts = Counter(f.check_id for f in findings)
    deductions: list[Deduction] = []
    for check_id in sorted(counts):
        spec = REGISTRY.get(check_id)
        if spec is None:
            raise ValueError(f"finding from unregistered check: {check_id}")
        raw = spec.weight * counts[check_id]
        deductions.append(
            Deduction(check_id, counts[check_id], min(spec.cap, raw), raw > spec.cap)
        )
    total = sum(d.points for d in deductions)
    return Score(max(0, MAX_SCORE - total), deductions)

import re
from collections.abc import Iterator
from dataclasses import dataclass

from claude_md.text import _FENCE

_HEADING = re.compile(r"^(#{1,6})\s+(.*?)\s*#*\s*$")


@dataclass(frozen=True)
class FencedBlock:
    start: int
    length: int


def prose_lines(text: str) -> Iterator[tuple[int, str]]:
    """Yield (1-based line number, line) for lines outside fenced blocks.

    Fence delimiter lines themselves are not yielded.
    """
    fence: str | None = None
    for number, line in enumerate(text.splitlines(), start=1):
        match = _FENCE.match(line)
        if match:
            if fence is None:
                fence = match.group(1)
            elif fence == match.group(1):
                fence = None
            continue
        if fence is None:
            yield number, line


def fenced_blocks(text: str) -> list[FencedBlock]:
    """Fenced blocks as (opening fence line, number of lines inside).

    An unterminated block runs to the end of the text.
    """
    lines = text.splitlines()
    blocks: list[FencedBlock] = []
    fence: str | None = None
    start = 0
    for number, line in enumerate(lines, start=1):
        match = _FENCE.match(line)
        if not match:
            continue
        if fence is None:
            fence, start = match.group(1), number
        elif fence == match.group(1):
            blocks.append(FencedBlock(start, number - start - 1))
            fence = None
    if fence is not None:
        blocks.append(FencedBlock(start, len(lines) - start))
    return blocks


_LIST_ITEM = re.compile(r"^\s*([-*+]|\d+[.)])\s")
_HRULE = re.compile(r"^\s*([-*_])(\s*\1){2,}\s*$")
_SETEXT = re.compile(r"^\s*(=+|-+)\s*$")
_LINK_DEF = re.compile(r"^\s{0,3}\[[^\]]+\]:\s")
_CONTINUATION_INDENT = 2
_CODE_INDENT = 4


def _frontmatter_end(lines: list[str]) -> int:
    if not lines or lines[0].rstrip() != "---":
        return 0
    for i in range(1, len(lines)):
        if lines[i].rstrip() == "---":
            return i + 1
    return 0


def paragraph_lines(text: str) -> Iterator[tuple[int, str]]:
    """Yield (1-based line number, line) for plain paragraph text only.

    Excludes frontmatter, fenced blocks, headings (ATX and setext), list items
    with their indented or lazy continuation lines, tables, blockquotes, HTML,
    link definitions, horizontal rules and indented code.
    """
    frontmatter_end = _frontmatter_end(text.splitlines())
    lines = dict(prose_lines(text))
    container: str | None = None
    previous_blank = True
    previous = 0
    for number in sorted(lines):
        line = lines[number]
        lazy = number == previous + 1 and not previous_blank
        previous = number
        previous_blank = not line.strip()
        if number <= frontmatter_end or previous_blank:
            continue
        stripped = line.lstrip()
        indent = len(line) - len(stripped)
        if (
            _HRULE.match(line)
            or _SETEXT.match(line)
            or _LINK_DEF.match(line)
            or stripped.startswith(("#", "|", "<"))
        ):
            container = None
        elif stripped.startswith(">"):
            container = "quote"
        elif _LIST_ITEM.match(line):
            container = "list"
        elif (
            container == "list"
            and (indent >= _CONTINUATION_INDENT or lazy)
            or container == "quote"
            and lazy
        ):
            pass
        else:
            container = None
            if indent < _CODE_INDENT and not _SETEXT.match(lines.get(number + 1, "x")):
                yield number, line


def headings(lines: list[str]) -> list[tuple[int, int, str]]:
    found: list[tuple[int, int, str]] = []
    fenced = False
    for number, line in enumerate(lines, start=1):
        if line.lstrip().startswith(("```", "~~~")):
            fenced = not fenced
        elif not fenced and (match := _HEADING.match(line)):
            found.append((number, len(match.group(1)), match.group(2)))
    return found

import re

from claude_md.checks._common import loaded
from claude_md.checks._markdown import (
    fenced_blocks,
    paragraph_lines,
    prose_lines,
)
from claude_md.findings import Context, Finding, Source, check
from claude_md.model import LoadedFile

BEST_PRACTICES = Source("docs", "https://code.claude.com/docs/en/best-practices")
HEURISTIC = Source("heuristic", None)

LINTER_PATTERNS = [
    r"indent(ation)?\s*(size|with|using)?\s*\d",
    r"(tab|space)s?\s*(for|as)\s*indent",
    r"semicolon",
    r"trailing\s*(comma|whitespace|space)",
    r"single\s*quotes?\s*(vs|or|over)\s*double",
    r"double\s*quotes?\s*(vs|or|over)\s*single",
    r"max\s*line\s*length",
    r"prettier",
    r"eslint\s*(rule|config)",
]

VAGUE_PATTERNS = [
    r"(format|write|style)\s*(code|it)?\s*properly",
    r"follow\s*best\s*practices",
    r"keep\s*(code|it)\s*clean",
    r"write\s*good\s*(code|tests)",
    r"be\s*careful\s*with",
    r"try\s*to\s*(avoid|use|keep)",
]

MAX_CODE_BLOCK_LINES = 5
MIN_NARRATIVE_LINES = 3


@check("vague-instruction", BEST_PRACTICES, weight=3, cap=9)
def vague_instruction(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    found: list[Finding] = []
    for file in loaded(files):
        for number, line in prose_lines(file.text):
            lowered = line.lower()
            for pattern in VAGUE_PATTERNS:
                match = re.search(pattern, lowered)
                if match:
                    found.append(
                        Finding(
                            "vague-instruction",
                            "warning",
                            file.path,
                            number,
                            f"{file.path}:{number} has a vague instruction: "
                            f"'{match.group()}'.",
                            "Replace it with a specific, verifiable directive, "
                            "such as the exact command or convention to follow.",
                            BEST_PRACTICES,
                        )
                    )
    return found


@check("linter-rule", HEURISTIC, weight=2, cap=6)
def linter_rule(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    found: list[Finding] = []
    for file in loaded(files):
        hit = next(
            (
                (number, match.group())
                for number, line in prose_lines(file.text)
                for pattern in LINTER_PATTERNS
                if (match := re.search(pattern, line.lower()))
            ),
            None,
        )
        if hit:
            number, text = hit
            found.append(
                Finding(
                    "linter-rule",
                    "issue",
                    file.path,
                    number,
                    f"{file.path}:{number} states a formatting rule "
                    f"('{text}') that a linter or formatter normally enforces.",
                    "Move the rule into the formatter or linter config and "
                    "remove it from this file.",
                    HEURISTIC,
                )
            )
    return found


@check("narrative-paragraph", HEURISTIC, weight=1, cap=3)
def narrative_paragraph(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    return [
        Finding(
            "narrative-paragraph",
            "suggestion",
            file.path,
            run[0],
            f"{file.path}:{run[0]} contains a prose paragraph of {len(run)} lines.",
            "Rewrite it as short bullet points, one instruction each.",
            HEURISTIC,
        )
        for file in loaded(files)
        for run in _prose_runs(file.text)
        if len(run) >= MIN_NARRATIVE_LINES
    ]


def _prose_runs(text: str) -> list[list[int]]:
    runs: list[list[int]] = []
    for number, _ in paragraph_lines(text):
        if runs and number == runs[-1][-1] + 1:
            runs[-1].append(number)
        else:
            runs.append([number])
    return runs


@check("code-block-long", HEURISTIC, weight=1, cap=3)
def code_block_long(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    return [
        Finding(
            "code-block-long",
            "suggestion",
            file.path,
            block.start,
            f"{file.path}:{block.start} contains a code block of {block.length} lines "
            f"(over {MAX_CODE_BLOCK_LINES}).",
            "Point to the real file as file:line instead of pasting the code.",
            HEURISTIC,
        )
        for file in loaded(files)
        for block in fenced_blocks(file.text)
        if block.length > MAX_CODE_BLOCK_LINES
    ]

import re
from collections.abc import Iterator

from claude_md.checks._common import loaded
from claude_md.checks._markdown import headings, prose_lines
from claude_md.discovery import _import_tokens, _looks_like_path
from claude_md.findings import Context, Finding, Source, check
from claude_md.model import LoadedFile, LoadMode

MEMORY = Source("docs", "https://code.claude.com/docs/en/memory")

MIN_SCOPED_LINES = 3

_SCOPED_LINE = re.compile(
    r"^\s*(?:(?:[-*+]|\d+[.)])\s+)?when\s+(?:editing|working\s+in|touching)\b(.*)$",
    re.IGNORECASE,
)
_PATH_SPAN = re.compile(r"`[^`\n]*[/*][^`\n]*`")
_BARE_PATH = re.compile(r"(?<![\w`])(?:\*+[\w.*/\-]+|[\w.\-]+/[\w.\-*/]*)")
_CODE_SPAN = re.compile(r"(`+)(?:(?!\1).)+?\1")
_IMPORT_WORD = r"(?P<imp>\bimport\w*)"
_SAVING = r"\b(?:save|saving|reduce|reducing|cut|cutting|lower|lowering)\s+(?:\w+\s+){0,2}(?:context|tokens?)\b"
_NEAR = r"[^.!?]{0,80}?"
_MISCONCEPTION = (
    re.compile(_IMPORT_WORD + _NEAR + _SAVING, re.IGNORECASE),
    re.compile(_SAVING + _NEAR + _IMPORT_WORD, re.IGNORECASE),
)

SCOPE_FIX = (
    "Move these rules into a `.claude/rules/<name>.md` file with `paths:` "
    "frontmatter listing the globs they apply to, or into a nested CLAUDE.md "
    "in the directory they cover, so they only load when Claude works on "
    "matching files."
)
IMPORT_FIX = (
    "Keep the import if it helps organise the file, but do not count on it "
    "to shrink context. To load rules only when relevant, use `paths:` "
    "frontmatter in `.claude/rules/` or a nested CLAUDE.md."
)


@check("scope-candidate", MEMORY, weight=1, cap=3)
def scope_candidate(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    findings: list[Finding] = []
    for file in loaded(files):
        if file.mode is not LoadMode.ALWAYS:
            continue
        for number, title, count in _scoped_sections(file.text):
            findings.append(
                Finding(
                    "scope-candidate",
                    "suggestion",
                    file.path,
                    number,
                    f"{file.path}:{number} section '{title}' has {count} rules "
                    "that apply only when working on particular paths, yet it "
                    "loads for every task. Path-scoped rules and nested "
                    "CLAUDE.md files load only when they are relevant.",
                    SCOPE_FIX,
                    MEMORY,
                )
            )
    return findings


def _scoped_sections(text: str) -> Iterator[tuple[int, str, int]]:
    lines = text.splitlines()
    prose = dict(prose_lines(text))
    marks = headings(lines)
    for index, (number, _, title) in enumerate(marks):
        end = marks[index + 1][0] if index + 1 < len(marks) else len(lines) + 1
        count = sum(
            1
            for n in range(number + 1, end)
            if n in prose and _is_scoped_line(prose[n])
        )
        if count >= MIN_SCOPED_LINES:
            yield number, title, count


def _is_scoped_line(line: str) -> bool:
    match = _SCOPED_LINE.match(line)
    if not match:
        return False
    rest = match.group(1)
    if _PATH_SPAN.search(rest):
        return True
    return any(token.lower() != "and/or" for token in _BARE_PATH.findall(rest))


@check("import-misconception", MEMORY, weight=1, cap=2)
def import_misconception(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    findings: list[Finding] = []
    for file in loaded(files):
        if not any(_looks_like_path(t) for t in _import_tokens(file.text)):
            continue
        number = _first_claim_line(file.text)
        if number is None:
            continue
        findings.append(
            Finding(
                "import-misconception",
                "suggestion",
                file.path,
                number,
                f"{file.path}:{number} suggests imports save context. Imported "
                "files are loaded at launch alongside the file that imports "
                "them, so an @path import does not reduce context.",
                IMPORT_FIX,
                MEMORY,
            )
        )
    return findings


def _first_claim_line(text: str) -> int | None:
    for paragraph in _paragraphs(text):
        joined = " ".join(line for _, line in paragraph)
        hits = [m.start("imp") for rx in _MISCONCEPTION if (m := rx.search(joined))]
        if not hits:
            continue
        offset = min(hits)
        position = 0
        for number, line in paragraph:
            position += len(line) + 1
            if offset < position:
                return number
    return None


def _paragraphs(text: str) -> Iterator[list[tuple[int, str]]]:
    current: list[tuple[int, str]] = []
    for number, line in prose_lines(text):
        stripped = _CODE_SPAN.sub(lambda m: " " * len(m.group()), line)
        if stripped.strip() and (not current or current[-1][0] == number - 1):
            current.append((number, stripped))
            continue
        if current:
            yield current
        current = [(number, stripped)] if stripped.strip() else []
    if current:
        yield current

import re
from dataclasses import dataclass

from claude_md.checks._common import loaded
from claude_md.checks._markdown import fenced_blocks, headings
from claude_md.findings import Context, Finding, Source, check
from claude_md.model import LoadedFile

BEST_PRACTICES = Source("docs", "https://code.claude.com/docs/en/best-practices")

MIN_TREE_LINES = 3
MIN_DEPENDENCY_RUN = 5
MAX_SECTION_LINES = 10

_TREE_GLYPH = re.compile(r"[├└]──")
_PATH_TOKEN = re.compile(r"^[\w.\-]+/$|^[\w\-]+(\.[\w\-]+)+$")
_DEPENDENCY = re.compile(
    r"""^\s*(?:[-*+]\s+)?["'`]?[A-Za-z][\w.\-]*(?:\[[\w,]+\])?["'`]?
    \s*(?:==|>=|<=|~=|\^|@|:|\s)\s*["'`]?v?\d+(?:\.\d+)+[\w.+\-]*["'`]?,?\s*$""",
    re.VERBOSE,
)
_DERIVABLE_HEADING = re.compile(r"architecture|project\s+structure", re.IGNORECASE)
_LIST_ITEM = re.compile(r"^\s*([-*+]|\d+[.)])\s")

FIX = (
    "Delete it with the user's approval, or replace it with a one-line "
    "pointer to the real file or command."
)
SUFFIX = "Claude can read this from the code or config, so it can usually be cut."


@dataclass(frozen=True)
class _Hit:
    line: int
    shape: str


@check("derivable-content", BEST_PRACTICES, weight=2, cap=6)
def derivable_content(files: list[LoadedFile], ctx: Context) -> list[Finding]:
    return [
        Finding(
            "derivable-content",
            "issue",
            file.path,
            hit.line,
            f"{file.path}:{hit.line} looks like {hit.shape}. {SUFFIX}",
            FIX,
            BEST_PRACTICES,
        )
        for file in loaded(files)
        for hit in _hits(file.text)
    ]


def _hits(text: str) -> list[_Hit]:
    lines = text.splitlines()
    hits = _tree_hits(lines) + _dependency_hits(lines)
    hits += _section_hits(lines, [h.line for h in hits])
    return sorted(hits, key=lambda h: h.line)


def _tree_hits(lines: list[str]) -> list[_Hit]:
    hits: list[_Hit] = []
    for block in fenced_blocks("\n".join(lines)):
        body = lines[block.start : block.start + block.length]
        if _is_tree(body):
            hits.append(_Hit(block.start, "a directory tree"))
    return hits


def _is_tree(body: list[str]) -> bool:
    if sum(1 for line in body if _TREE_GLYPH.search(line)) >= MIN_TREE_LINES:
        return True
    content = [line for line in body if line.strip()]
    if len(content) <= MIN_TREE_LINES:
        return False
    pathlike = [line for line in content if _PATH_TOKEN.match(line.strip())]
    indents = {len(line) - len(line.lstrip()) for line in pathlike}
    return len(pathlike) >= 0.8 * len(content) and len(indents) >= 2


def _dependency_hits(lines: list[str]) -> list[_Hit]:
    hits: list[_Hit] = []
    run_start = 0
    for number, line in enumerate(lines + [""], start=1):
        if _DEPENDENCY.match(line):
            run_start = run_start or number
            continue
        if run_start and number - run_start >= MIN_DEPENDENCY_RUN:
            hits.append(_Hit(run_start, "a dependency list"))
        run_start = 0
    return hits


def _section_hits(lines: list[str], covered: list[int]) -> list[_Hit]:
    """Long Architecture or Project structure sections made mostly of list items.

    Sections that already contain another hit are skipped, so each block is
    reported once.
    """
    marks = headings(lines)
    hits: list[_Hit] = []
    for index, (number, level, title) in enumerate(marks):
        if not _DERIVABLE_HEADING.search(title):
            continue
        end = next(
            (n for n, lvl, _ in marks[index + 1 :] if lvl <= level),
            len(lines) + 1,
        )
        body = [line for line in lines[number : end - 1] if line.strip()]
        if any(number < line < end for line in covered):
            continue
        items = sum(1 for line in body if _LIST_ITEM.match(line))
        if len(body) > MAX_SECTION_LINES and items * 2 >= len(body):
            hits.append(_Hit(number, f"a long '{title}' section"))
    return hits

import re

CJK_RANGES = [
    (0x3000, 0x303F),
    (0x3040, 0x309F),
    (0x30A0, 0x30FF),
    (0x4E00, 0x9FFF),
    (0xAC00, 0xD7AF),
    (0x1100, 0x11FF),
    (0x3130, 0x318F),
]

_FENCE = re.compile(r"^\s*(```|~~~)")
_PATHS_KEY = re.compile(r"^paths:[ \t]*(.*)$")
_LIST_ITEM = re.compile(r"^\s*-\s+(.*)$")


def is_cjk_char(ch: str) -> bool:
    cp = ord(ch)
    return any(start <= cp <= end for start, end in CJK_RANGES)


def estimate_tokens(text: str) -> int:
    """
    Language-aware token estimation.
    English: ~4 chars per token. CJK: ~1.5 chars per token.
    """
    if not text:
        return 0

    english_chars = 0
    cjk_chars = 0
    other_chars = 0

    for ch in text:
        if is_cjk_char(ch):
            cjk_chars += 1
        elif ord(ch) < 128:
            english_chars += 1
        else:
            other_chars += 1

    tokens = (english_chars / 4) + (cjk_chars / 1.5) + (other_chars / 3)
    return int(tokens)


def strip_html_comments(text: str) -> str:
    out: list[str] = []
    fence: str | None = None
    in_comment = False
    for line in text.splitlines(keepends=True):
        if in_comment:
            end = line.find("-->")
            if end == -1:
                continue
            in_comment = False
            rest = line[end + 3 :]
            if rest.strip():
                out.append(rest)
            continue
        match = _FENCE.match(line)
        if match:
            if fence is None:
                fence = match.group(1)
            elif fence == match.group(1):
                fence = None
        if fence is None and not match and line.lstrip().startswith("<!--"):
            start = line.index("<!--")
            end = line.find("-->", start + 4)
            if end == -1:
